		const erlaubt = Number(c.anzahl_erinnerungen || 0);
		aufgaben.push({
			aktion: gesendet < erlaubt ? 'erinnerung' : 'eskalation',
			...ref,
			freigabe_id: '',
			version: v.version ?? null,
			erinnerungen_gesendet: gesendet,
